import json

with open('/Users/rmuller/dev/nac-nd-gui/.claude/memory_logs/current.json', 'r') as f:
    data = json.load(f)

entries = data.get('entries', [])
print(f"Current log entries: {len(entries)}\n")

work_operations = []
meta_memory_operations = []

for entry in entries:
    tool_name = entry.get('tool_data', {}).get('tool_name', '')
    tool_input = entry.get('tool_data', {}).get('tool_input', {})

    is_meta_memory = False

    if tool_name == 'Task':
        subagent = tool_input.get('subagent_type', '')
        if subagent in ['au-update', 'au-promotion']:
            is_meta_memory = True
    elif tool_name == 'Bash':
        command = tool_input.get('command', '')
        if any(kw in command.lower() for kw in ['archive', 'current.json', 'memory_logs', 'wc -c', 'memory/project', 'memory/*.md']):
            is_meta_memory = True
    elif tool_name == 'Write':
        file_path = tool_input.get('file_path', '')
        if 'CROSS_TIER_PROMOTION_ANALYSIS' in file_path or 'MEMORY_LOG_PROCESSING' in file_path:
            is_meta_memory = True
    elif tool_name == 'Edit':
        file_path = tool_input.get('file_path', '')
        if 'session-history.md' in file_path or 'PROMOTION' in file_path:
            is_meta_memory = True

    if is_meta_memory:
        meta_memory_operations.append(entry)
    else:
        work_operations.append(entry)

print(f"Work operations: {len(work_operations)}")
print(f"Meta-memory operations: {len(meta_memory_operations)}")
print(f"Meta-memory filtering rate: {len(meta_memory_operations)/len(entries)*100:.1f}%\n")

if work_operations:
    print("Work Operations:")
    print("=" * 60)
    for i, entry in enumerate(work_operations, 1):
        tool_name = entry.get('tool_data', {}).get('tool_name', '')
        print(f"{i}. {tool_name}")
else:
    print("No work operations to process - all meta-memory.")

ANALYZE_CURRENT_LOG
